package com.dentalclinic.patientcare.controller;
import com.dentalclinic.patientcare.entity.*;import com.dentalclinic.patientcare.service.PatientCareService;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/patient-care") @CrossOrigin(origins="http://localhost:5173") public class PatientCareController {private final PatientCareService service;public PatientCareController(PatientCareService s){service=s;}
@GetMapping("/patients") public List<PatientCareRecord> all(@RequestParam(required=false)String search,@RequestParam(required=false)Boolean active){return service.patients(search,active);}@GetMapping("/patients/{id}") public PatientCareRecord one(@PathVariable Long id){return service.patient(id);}@PostMapping("/patients") @ResponseStatus(HttpStatus.CREATED) public PatientCareRecord create(@Valid @RequestBody PatientCareRecord p){return service.save(p);}@PutMapping("/patients/{id}") public PatientCareRecord update(@PathVariable Long id,@Valid @RequestBody PatientCareRecord p){return service.update(id,p);}@DeleteMapping("/patients/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){service.delete(id);}
@GetMapping("/patients/{id}/history") public List<CareHistoryEntry> history(@PathVariable Long id){return service.history(id);}@PostMapping("/patients/{id}/history") @ResponseStatus(HttpStatus.CREATED) public CareHistoryEntry historyAdd(@PathVariable Long id,@Valid @RequestBody CareHistoryEntry x){return service.addHistory(id,x);}@DeleteMapping("/history/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void historyDelete(@PathVariable Long id){service.deleteHistory(id);}
@GetMapping("/patients/{id}/consents") public List<ConsentRecord> consents(@PathVariable Long id){return service.consents(id);}@PostMapping("/patients/{id}/consents") @ResponseStatus(HttpStatus.CREATED) public ConsentRecord consentAdd(@PathVariable Long id,@Valid @RequestBody ConsentRecord x){return service.addConsent(id,x);}@DeleteMapping("/consents/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void consentDelete(@PathVariable Long id){service.deleteConsent(id);}
@GetMapping("/recalls") public List<PatientCareRecord> recalls(@RequestParam(defaultValue="30")int days){return service.recalls(days);}@PostMapping("/patients/{id}/submissions") @ResponseStatus(HttpStatus.CREATED) public PatientSubmission submit(@PathVariable Long id,@Valid @RequestBody PatientSubmission x){return service.submit(id,x);}@GetMapping("/patients/{id}/submissions") public List<PatientSubmission> submissions(@PathVariable Long id){return service.submissions(id);}}
// LEADER MERGE: Endpoint prefix /api/patient-care is intentionally unique. If your gateway/API convention differs, change only this @RequestMapping.
